<?php
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/layout.php';
require_user();$orders=sb('GET','rest/v1/pedidos?select=*&order=created_at.desc',null,true);$lines=sb('GET','rest/v1/compras?select=*&order=created_at.desc',null,true);$byOrder=[];foreach($lines as $line)$byOrder[$line['id_pedido']][]=$line;
