<main class="container page-section orders-page" id="contenido"><div class="page-heading"><div><h1>Mis pedidos</h1></div><a class="button button-light" href="<?=h(url('index.php#catalogo'))?>">Ver productos<?=icon('arrow')?></a></div>
<?php if(!$orders):?><div class="empty-state"><?=icon('box')?><h2>Todavía no tenés pedidos</h2><a class="button" href="<?=h(url('index.php#catalogo'))?>">Ver productos<?=icon('arrow')?></a></div><?php else:?>
<div class="orders-list"><?php foreach($orders as $i=>$order):?><details class="order-card" <?=$i===0?'open':''?>><summary><span class="order-number"><?=icon('box')?><span><strong>Pedido #<?=h(strtoupper(substr($order['id'],0,8)))?></strong><small><?=date('d/m/Y · H:i',strtotime($order['created_at']))?></small></span></span><span class="order-status"><?=h($states[$order['estado']]??$order['estado'])?></span><strong class="order-amount"><?=money($order['total'])?></strong><?=icon('chevron','order-chevron')?></summary><div class="order-lines"><?php foreach($byOrder[$order['id']]??[] as $line):?><div class="order-line"><img src="<?=h(image_url($line['imagen_producto']))?>" alt="<?=h($line['nombre_producto'])?>" width="80" height="80"><div><span class="eyebrow"><?=h($line['marca_producto'])?></span><h3><?=h($line['nombre_producto'])?></h3><p><?=(int)$line['cantidad']?> × <?=money($line['precio_unitario'])?></p><?php if($line['id_producto']===null):?><small class="muted">Este artículo fue retirado del catálogo.</small><?php endif;?></div><strong><?=money($line['subtotal'])?></strong></div><?php endforeach;?></div><div class="order-footnote">Compra de prueba, sin cobro</div></details><?php endforeach;?></div>
<?php endif;?></main>
